1	package cli
2	
3	import (
4		"bytes"
5		"context"
6		"encoding/json"
7		"errors"
8		"fmt"
9		"os"
10		"path/filepath"
11		"sort"
12		"strings"
13		"time"
14	
15		"github.com/entireio/entire-brain/factmerge"
16		"github.com/entireio/entire-brain/internal/factgitmeta"
17		"github.com/entireio/entire-brain/internal/factsync"
18	
19		"github.com/spf13/cobra"
20	)
21	
22	const (
23		// factsBackendLocalGitmeta is the default: a bare, on-disk git-meta store
24		// under the plugin cache; fully local, no network/entiredb/Postgres.
25		factsBackendLocalGitmeta = "local-gitmeta"
26		// factsBackendHTTP drives the hosted entire-api FactSetStore (factsync.HTTPServer).
27		factsBackendHTTP = "http"
28		// envFactsBackend selects the backend when --facts-backend is unset.
29		envFactsBackend = "ENTIRE_BRAIN_FACTS_BACKEND"
30	)
31	
32	// factsSyncOptions bundles the flag state for `facts sync`.
33	type factsSyncOptions struct {
34		branch  string
35		backend string
36		member  string
37		// http backend only (mirror publish's flag/env resolution):
38		apiURL string
39		token  string
40		repoID string
41	
42		jsonOut bool
43	}
44	
45	func newFactsSyncCommand(opts Options) *cobra.Command {
46		var syncOpts factsSyncOptions
47		cmd := &cobra.Command{
48			Use:   "sync",
49			Short: "Read-merge-CAS this branch's local memories into the shared memory-set head",
50			Long: `sync runs the factsync read-merge-CAS loop for the current branch: pull the
51	current memory-set head, keep-both merge this member's local memories into it,
52	and compare-and-swap the result back; retrying on a losing swap.
53	
54	Backends (--memories-backend, or ` + envFactsBackend + `):
55	  local-gitmeta  (default) a bare, on-disk git-meta store under the brain cache
56	                 (<cache>/brain/<repo-key>/gitmeta.git); fully local, no network,
57	                 entiredb, or Postgres.
58	  http           the hosted entire-api FactSetStore; opt-in. Target resolves
59	                 flag > env > connected binding: --api-url/ENTIRE_API_URL,
60	                 --repo-id/ENTIRE_REPO_ID, --token/ENTIRE_API_TOKEN; on a
61	                 connected repo the binding and a minted token are the default.`,
62			Args: cobra.NoArgs,
63			RunE: func(cmd *cobra.Command, args []string) error {
64				return runFactsSync(cmd, opts, syncOpts)
65			},
66		}
67		cmd.Flags().StringVar(&syncOpts.branch, "branch", "", "Branch to sync (default: current branch)")
68		cmd.Flags().StringVar(&syncOpts.backend, "memories-backend", "", "Memory-set backend: local-gitmeta (default) or http")
69		cmd.Flags().StringVar(&syncOpts.member, "member", "", "Member identity stamped on cross-member proposals (default: git user.email)")
70		cmd.Flags().StringVar(&syncOpts.repoID, "repo-id", "", "Target repo id for the http backend (overrides ENTIRE_REPO_ID)")
71		cmd.Flags().StringVar(&syncOpts.apiURL, "api-url", "", "Entire API base URL for the http backend, https:// (overrides ENTIRE_API_URL)")
72		cmd.Flags().StringVar(&syncOpts.token, "token", "", "Entire API bearer token for the http backend (overrides ENTIRE_API_TOKEN)")
73		cmd.Flags().BoolVar(&syncOpts.jsonOut, "json", false, "Emit the sync result as JSON")
74		// --facts-backend predates the facts→memories rename; keep it working.
75		legacyFlagAlias(cmd.Flags(), "facts-backend", "memories-backend")
76		return cmd
77	}
78	
79	func runFactsSync(cmd *cobra.Command, opts Options, syncOpts factsSyncOptions) error {
80		ctx := cmd.Context()
81	
82		repoDir, local, err := resolveLocalTargetRepoDir(ctx, opts.Runner, agentSurfaceTarget(opts, nil))
83		if err != nil {
84			return err
85		}
86		if !local {
87			return fmt.Errorf("memories sync requires a local repository path")
88		}
89		storage, err := repoStoragePaths(ctx, opts.Runner, opts.Env, repoDir)
90		if err != nil {
91			return err
92		}
93	
94		branch := strings.TrimSpace(syncOpts.branch)
95		if branch == "" {
96			if current, gitErr := gitScalar(ctx, opts.Runner, repoDir, "branch", "--show-current"); gitErr == nil {
97				branch = strings.TrimSpace(current)
98			}
99		}
100		if branch == "" {
101			branch = distillDefaultBranch
102		}
103	
104		facts, err := loadFacts(storage.BrainDir, branch)
105		if err != nil {
106			return err
107		}
108		memberID := resolveSyncMemberID(ctx, opts.Runner, repoDir, syncOpts.member)
109	
110		srv, repoID, backendLabel, err := buildFactsSyncBackend(ctx, opts, resolveFactsBackendName(syncOpts.backend), storage, repoDir, syncOpts)
111		if err != nil {
112			return err
113		}
114	
115		// The merge runs on this runner (ADR-P1-E); the backend only stores the blob
116		// and CAS-swaps the head. Sync retries on a losing swap and never drops a
117		// member's fact.
118		res, err := factsync.Sync(ctx, srv, repoID, branch, memberID, facts, opts.Now().UTC())
119		if err != nil {
120			return err
121		}
122		// The binding records the fact-head sync, independently of proposal queue health.
123		if hosted, ok := srv.(*factsync.HTTPServer); ok {
124			if err := writeHostedFactsBinding(storage.BrainDir, branch, repoID, hosted.BaseURL); err != nil {
125				return fmt.Errorf("memories sync: record hosted target: %w", err)
126			}
127		}
128	
129		if err := persistFactsSyncProposals(storage.BrainDir, branch, res.Proposals); err != nil {
130			return err
131		}
132	
133		// Publish the WHOLE local review queue — this sync's raised conflicts plus any
134		// earlier entries that never reached the shared set (a previously failed
135		// publish, or a queue populated before a hosted backend was configured) — so
136		// other members can review them with `facts proposals`. Only backends that
137		// serve the queue (the hosted http one) can take them; the local git-meta
138		// store has no proposal set and is left untouched. After a successful publish
139		// the hosted set is the source of truth, and the local queue is reconciled to
140		// it so a conflict a teammate settled hosted-side stops being re-listed (and
141		// re-appliable) here.
142		//
143		// Failure discipline: a backend that does not serve the queue at all
144		// (entire-api predating the endpoint) is a warning — the sync itself is
145		// complete and the queue is a hosted add-on. Any OTHER failure fails the
146		// command: the facts already advanced the shared head, so a swallowed
147		// publish error would leave conflicts only this member can see.
148		var pub factsync.PublishResult
149		var pubErr error
150		if transport, hasQueue := srv.(factsync.ProposalTransport); hasQueue {
151			localQueue, queueErr := loadFactProposals(storage.BrainDir, branch)
152			if queueErr != nil {
153				return fmt.Errorf("memories sync: load review queue: %w", queueErr)
154			}
155			ledger, ledgerErr := loadSharedProposalLedger(storage.BrainDir, branch)
156			if ledgerErr != nil {
157				return fmt.Errorf("memories sync: load shared-proposal ledger: %w", ledgerErr)
158			}
159			// The post-sync head gates what may be published AND supplies the settlements
160			// mirrored into local facts below. Sync already computed it, so take it from
161			// the result rather than issuing another Current — that read is a full network
162			// round-trip against the hosted backend on every sync. Fall back to a real
163			// read only if the result carries nothing (an empty converged head).
164			hostedFacts := res.Facts
165			if len(hostedFacts) == 0 {
166				fetched, headErr := readSharedFactHead(ctx, srv, repoID, branch)
167				if headErr != nil {
168					fmt.Fprintf(cmd.ErrOrStderr(), "warning: could not read the shared memory head; skipping settled-proposal checks this sync: %v\n", headErr)
169				}
170				hostedFacts = fetched
171			}
172	
173			// Publish only entries that are member-attributed AND have never reached
174			// the hosted set. Distill's single-user review backlog shares the same
175			// local queue but carries no ProposedBy: it is this member's private
176			// pending-review state, not a cross-member conflict, and must never
177			// egress (its unattributed id derivation would also collide across
178			// members). An already-shared entry absent from the hosted set was
179			// settled by another member; re-publishing it would resurrect exactly
180			// the conflict they resolved, so reconciliation prunes it instead.
181			//
182			// The ledger alone is not enough: it lives in this checkout, so a SECOND
183			// clone of the same member starts with an empty one and would republish
184			// conflicts the team already settled. The shared head is the cross-clone
185			// source of truth — a settled conflict is no longer applicable to it — so
186			// an unapplicable proposal is treated as settled regardless of the ledger.
187			toPublish := make([]factProposal, 0, len(localQueue))
188			for _, p := range localQueue {
189				if strings.TrimSpace(p.ProposedBy) == "" {
190					continue
191				}
192				if _, shared := ledger[factsync.ProposalID(p)]; shared {
193					continue
194				}
195				if len(hostedFacts) > 0 && !proposalStillOpenAgainst(hostedFacts, p) {
196					continue
197				}
198				toPublish = append(toPublish, p)
199			}
200			if len(toPublish) > 0 {
201				pub, pubErr = factsync.PublishRaised(ctx, transport, repoID, branch, toPublish)
202				switch {
203				case pubErr == nil:
204				case errors.Is(pubErr, factsync.ErrProposalQueueUnsupported):
205					fmt.Fprintf(cmd.ErrOrStderr(), "warning: backend has no shared review queue; %d proposal(s) stay in the local queue ('memories review'): %v\n", len(localQueue), pubErr)
206				default:
207					return fmt.Errorf("memories sync: memories head advanced to %s, but sharing %d proposal(s) to the review queue failed: %w (they remain reviewable locally with 'memories review', and the next 'memories sync' republishes them)",
208						refOrNone(res.NewRef), len(toPublish), pubErr)
209				}
210			} else if set, listErr := transport.ListProposals(ctx, repoID, branch); listErr != nil {
211				// Nothing needed sharing: this list exists only to reconcile the
212				// local queue, so a transient failure must not fail a sync whose
213				// head-advance fully succeeded. The next sync reconciles.
214				pubErr = listErr
215				if !errors.Is(listErr, factsync.ErrProposalQueueUnsupported) {
216					fmt.Fprintf(cmd.ErrOrStderr(), "warning: could not read the shared review queue to reconcile the local one; will retry next sync: %v\n", listErr)
217				}
218			} else {
219				pub = factsync.PublishResult{Ref: set.Ref, Open: len(set.Proposals), Proposals: set.Proposals}
220				if pub.Proposals == nil {
221					pub.Proposals = []factsync.OpenProposal{}
222				}
223			}
224			if pubErr == nil && pub.Proposals != nil {
225				// hostedFacts was read above; a failed read only costs this sync's
226				// mirroring — the queue entry stays until reconciled, so the next
227				// sync retries.
228				if err := reconcileLocalProposalQueue(storage.BrainDir, branch, pub.Proposals, hostedFacts, opts.Now().UTC()); err != nil {
229					return fmt.Errorf("memories sync: reconcile review queue: %w", err)
230				}
231			}
232		}
233	
234		if syncOpts.jsonOut {
235			payload := map[string]any{
236				"branch":             branch,
237				"backend":            backendLabel,
238				"member":             memberID,
239				"published":          res.Published,
240				"ref":                res.NewRef,
241				"attempts":           res.Attempts,
242				"proposals":          res.Proposals,
243				"facts":              len(facts),
244				"proposals_shared":   pub.Published,
245				"proposals_open":     pub.Open,
246				"proposals_head_ref": pub.Ref,
247			}
248			if pubErr != nil {
249				payload["proposals_share_error"] = pubErr.Error()
250			}
251			return writeJSON(cmd, payload)
252		}
253	
254		out := cmd.OutOrStdout()
255		if res.Published {
256			fmt.Fprintf(out, "synced %d local memory(ies) on %s via %s: head advanced to %s (%d attempt(s))\n",
257				len(facts), branch, backendLabel, res.NewRef, res.Attempts)
258		} else {
259			fmt.Fprintf(out, "synced %d local memory(ies) on %s via %s: no change; head at %s (%d attempt(s))\n",
260				len(facts), branch, backendLabel, refOrNone(res.NewRef), res.Attempts)
261		}
262		if len(res.Proposals) > 0 {
263			fmt.Fprintf(out, "%d cross-member conflict(s) queued for review:\n", len(res.Proposals))
264			for _, p := range res.Proposals {
265				fmt.Fprintf(out, "  %s %s -> %s (by %s, confidence %.2f)\n", p.Action, p.CandidateID, p.TargetID, p.ProposedBy, p.Confidence)
266			}
267			if pub.Published {
268				fmt.Fprintf(out, "shared to the review queue (%d open); resolve with 'memories proposals apply|reject <proposal>'\n", pub.Open)
269			}
270		}
271		return nil
272	}
273	
274	// persistFactsSyncProposals appends cross-member conflicts to the same durable
275	// queue consumed by facts review/status and the recall pending-review guard.
276	// The brain write lock makes the read-merge-write atomic with other local
277	// writers, while writeFactProposals supplies stable ordering and deduplication.
278	func persistFactsSyncProposals(brainDir, branch string, proposals []factProposal) error {
279		if len(proposals) == 0 {
280			return nil
281		}
282		return withBrainWriteLock(brainDir, func() error {
283			existing, err := loadFactProposals(brainDir, branch)
284			if err != nil {
285				return fmt.Errorf("memories sync: load review queue: %w", err)
286			}
287			if err := writeFactProposals(brainDir, branch, append(existing, proposals...)); err != nil {
288				return fmt.Errorf("memories sync: persist review queue: %w", err)
289			}
290			return nil
291		})
292	}
293	
294	// factsSharedLedgerFileName records, per branch, the derived ids of local
295	// proposals that have REACHED the hosted open set at some point. Without it a
296	// settled proposal (published, then resolved by a teammate: gone from the
297	// hosted set) is indistinguishable from a never-published one, and the next
298	// sync would resurrect exactly the conflict the teammate settled.
299	const factsSharedLedgerFileName = "proposals-shared.json"
300	
301	func factsSharedLedgerRelPath(branch string) string {
302		return filepath.ToSlash(filepath.Join(factsBranchRelDir(branch), factsSharedLedgerFileName))
303	}
304	
305	func loadSharedProposalLedger(brainDir, branch string) (map[string]struct{}, error) {
306		path := filepath.Join(brainDir, filepath.FromSlash(factsSharedLedgerRelPath(branch)))
307		data, err := os.ReadFile(path)
308		if err != nil {
309			if os.IsNotExist(err) {
310				return map[string]struct{}{}, nil
311			}
312			return nil, err
313		}
314		var ids []string
315		if err := json.Unmarshal(data, &ids); err != nil {
316			return nil, fmt.Errorf("parse %s: %w", factsSharedLedgerRelPath(branch), err)
317		}
318		out := make(map[string]struct{}, len(ids))
319		for _, id := range ids {
320			out[id] = struct{}{}
321		}
322		return out, nil
323	}
324	
325	func writeSharedProposalLedger(brainDir, branch string, ids map[string]struct{}) error {
326		if len(ids) == 0 {
327			return removeBrainRelativeFile(brainDir, factsSharedLedgerRelPath(branch))
328		}
329		sorted := make([]string, 0, len(ids))
330		for id := range ids {
331			sorted = append(sorted, id)
332		}
333		sort.Strings(sorted)
334		data, err := json.Marshal(sorted)
335		if err != nil {
336			return err
337		}
338		return writeBrainRelativeFileAtomic(brainDir, factsSharedLedgerRelPath(branch), data, 0o600)
339	}
340	
341	// reconcileLocalProposalQueue rewrites the local review queue after a successful
342	// publish so it converges on the hosted open set: an entry the ledger says was
343	// shared but the hosted set no longer carries was settled by another member and
344	// is dropped; entries still hosted-open stay; entries never yet shared stay for
345	// the next publish. The ledger is then rewritten to the hosted set, which by
346	// definition holds every currently shared proposal.
347	// readSharedFactHead pulls the shared fact-set head and parses it. An absent head
348	// yields no records and no error — a branch nobody has synced yet is a normal state,
349	// not a failure. Only a transport fault or unparseable content is an error, and the
350	// caller degrades rather than failing a sync whose head-advance already succeeded.
351	func readSharedFactHead(ctx context.Context, srv factsync.Server, repoID, branch string) ([]factRecord, error) {
352		_, plaintext, found, err := srv.Current(ctx, repoID, branch)
353		if err != nil {
354			return nil, err
355		}
356		if !found || len(plaintext) == 0 {
357			return nil, nil
358		}
359		parsed, err := factmerge.ParseNDJSON(bytes.NewReader(plaintext))
360		if err != nil {
361			return nil, fmt.Errorf("parse shared memory head: %w", err)
362		}
363		// The head is written by every member with push access. Re-derive each
364		// record's content id before any of it reaches local state: this read feeds
365		// proposal reconciliation, which supersedes and removes LOCAL facts by id.
366		if err := factmerge.VerifyIdentities(parsed); err != nil {
367			return nil, fmt.Errorf("shared memory head for %s/%s is not trustworthy: %w", repoID, branch, err)
368		}
369		return parsed, nil
370	}
371	
372	// proposalStillOpenAgainst reports whether p is a live conflict against the shared
373	// head — both of its facts still present, and the target not already superseded by
374	// the candidate. A settled or stale proposal fails this and must not be republished.
375	//
376	// This is what makes settlement stick ACROSS CLONES: the shared-proposal ledger is
377	// per-checkout, so a second clone of the same member has no record of what was
378	// published and would resurrect conflicts the team already resolved. The head is
379	// the same for every clone.
380	func proposalStillOpenAgainst(hostedFacts []factRecord, p factProposal) bool {
381		ci := indexOfFact(hostedFacts, p.CandidateID)
382		ti := indexOfFact(hostedFacts, p.TargetID)
383		if ci < 0 || ti < 0 {
384			return false // one side is gone: merged away, retracted, or GC'd
385		}
386		if hostedFacts[ti].Status == factStatusSuperseded && hostedFacts[ti].SupersededBy == p.CandidateID {
387			return false // already superseded exactly as this proposal asked
388		}
389		if hostedFacts[ci].Status == factStatusSuperseded && hostedFacts[ci].SupersededBy == p.TargetID {
390			return false // settled the other way round
391		}
392		return true
393	}
394	
395	// settledHostedAsAccept reports whether the shared fact-set head shows p as
396	// ACCEPTED. A settled proposal carries no decision field, so the decision is
397	// derived from the effect ApplyProposal would have left on the head:
398	//
399	//	merge     accept removes the candidate and keeps the target
400	//	supersede accept flips the target to superseded, pointing at the candidate
401	//
402	// Anything else (both ids still present and merely unlinked, or a fact that has
403	// since moved on) reads as a reject: reject changes no fact status, so mirroring
404	// it locally is limited to clearing the conflict cross-link.
405	func settledHostedAsAccept(hostedFacts []factRecord, p factProposal) bool {
406		ci := indexOfFact(hostedFacts, p.CandidateID)
407		ti := indexOfFact(hostedFacts, p.TargetID)
408		if p.Action == factActionMerge {
409			return ci < 0 && ti >= 0
410		}
411		return ti >= 0 && hostedFacts[ti].Status == factStatusSuperseded && hostedFacts[ti].SupersededBy == p.CandidateID
412	}
413	
414	// applySettlementLocally folds a settlement another member made on the shared
415	// head into THIS member's local facts, using the same primitives the hosted
416	// side ran so the two cannot drift.
417	//
418	// Without this the settlement does not stick: the losing member's local copy
419	// still holds the retired fact, and the next sync's keep-both Promote re-adds it
420	// and re-raises the same conflict under a fresh id — an unresolvable loop for
421	// whichever member lost the merge.
422	func applySettlementLocally(facts []factRecord, p factProposal, accepted bool, now time.Time) ([]factRecord, bool) {
423		if !accepted {
424			// Reject: clear the local cross-link so the pair stops reading as
425			// conflicting. With either side absent there is no link to clear, so report
426			// no change rather than rewriting the fact store and bumping the source
427			// manifest for nothing.
428			if indexOfFact(facts, p.CandidateID) < 0 || indexOfFact(facts, p.TargetID) < 0 {
429				return facts, false
430			}
431			return rejectProposal(facts, p), true
432		}
433		updated, err := applyProposal(facts, p, now)
434		if err != nil {
435			// The local copy no longer holds both sides (already retracted, GC'd, or
436			// settled here). The hosted decision is still authoritative and already
437			// recorded; there is nothing left locally to reconcile.
438			return facts, false
439		}
440		return updated, true
441	}
442	
443	func reconcileLocalProposalQueue(brainDir, branch string, hosted []factsync.OpenProposal, hostedFacts []factRecord, now time.Time) error {
444		hostedIDs := make(map[string]struct{}, len(hosted))
445		for _, p := range hosted {
446			hostedIDs[p.ID] = struct{}{}
447		}
448		return withBrainWriteLock(brainDir, func() error {
449			ledger, err := loadSharedProposalLedger(brainDir, branch)
450			if err != nil {
451				return err
452			}
453			current, err := loadFactProposals(brainDir, branch)
454			if err != nil {
455				return err
456			}
457			// A settled entry may only be pruned once its settlement has been mirrored
458			// into local facts. Mirroring needs the shared head, so with no head to read
459			// the entry STAYS QUEUED and the next sync retries: pruning it here would
460			// drop the only record of what still needs mirroring, leaving the retired
461			// fact active locally with nothing left to reconcile it against — the exact
462			// defect this function exists to close, reintroduced through the back door.
463			canMirror := len(hostedFacts) > 0
464			next := make([]factProposal, 0, len(current))
465			settled := make([]factProposal, 0, len(current))
466			for _, p := range current {
467				id := factsync.ProposalID(p)
468				_, stillOpen := hostedIDs[id]
469				_, wasShared := ledger[id]
470				if stillOpen || !wasShared {
471					next = append(next, p)
472					continue
473				}
474				if !canMirror {
475					next = append(next, p) // settled, but keep it until it can be mirrored
476					continue
477				}
478				// Shared once, gone from the hosted set: another member settled it.
